const update = $input.first().json;

if (update.callback_query) {
  return [{
    json: {
      route: 'callback',
      callback_data: update.callback_query.data,
      chat_id: update.callback_query.message.chat.id,
      user_id: String(update.callback_query.from.id)
    }
  }];
}

const message = update.message || {};
const chatId = message.chat?.id;
const userId = String(message.from?.id || 'unknown');
const text = message.text || '';

if (text.startsWith('/start')) {
  return [{ json: { route: 'start', chat_id: chatId, user_id: userId } }];
}

if (message.document) {
  return [{
    json: {
      route: 'document',
      chat_id: chatId,
      user_id: userId,
      file_id: message.document.file_id,
      file_name: message.document.file_name || 'upload.xlsx',
      mime_type: message.document.mime_type || ''
    }
  }];
}

return [{ json: { route: 'other', chat_id: chatId, user_id: userId } }];

const route = $('Route Update').item.json;
return [{
  json: {
    chat_id: route.chat_id,
    user_id: route.user_id,
    file_id: route.file_id,
    file_name: route.file_name,
    mime_type: route.mime_type
  }
}];

const route = $('Route Update').item.json;
const items = $input.all();
const rows = items.map((item) => item.json);

if (!rows.length) {
  return [{
    json: {
      chat_id: route.chat_id,
      user_id: route.user_id,
      file_name: route.file_name,
      valid: false,
      message: 'Database check failed: file is empty or could not be parsed.',
      issues: ['Empty file'],
      columns: 0,
      total_rows: 0,
      non_empty_rows: 0,
      duplicate_rows: 0,
      header: [],
      csv_rows: []
    }
  }];
}

const header = Object.keys(rows[0] || {});
const dataRows = rows.map((row) => header.map((key) => {
  const value = row[key];
  return value === undefined || value === null ? '' : String(value);
}));

const nonEmptyRows = dataRows.filter((row) => row.some((cell) => String(cell).trim() !== ''));
const unique = new Set(nonEmptyRows.map((row) => JSON.stringify(row)));
const duplicateRows = nonEmptyRows.length - unique.size;
const emptyHeaderCells = header.filter((h) => !String(h).trim()).length;

const issues = [];
if (!header.length) issues.push('Header row is missing.');
if (emptyHeaderCells) issues.push(`${emptyHeaderCells} empty header cell(s) found.`);
if (!nonEmptyRows.length) issues.push('No data rows found after header.');
if (duplicateRows > 0) issues.push(`${duplicateRows} duplicate data row(s) found.`);

const valid = issues.length === 0;
let message = '';
if (valid) {
  message = `Database check completed successfully.\nRows: ${nonEmptyRows.length}\nColumns: ${header.length}\nConverted to CSV and ready.`;
} else {
  message = `Database check found issues:\n- ${issues.join('\n- ')}\n\nRows: ${nonEmptyRows.length}\nColumns: ${header.length}`;
}

const csvRows = [header, ...dataRows];

return [{
  json: {
    chat_id: route.chat_id,
    user_id: route.user_id,
    file_name: route.file_name,
    valid,
    message,
    issues,
    columns: header.length,
    total_rows: dataRows.length,
    non_empty_rows: nonEmptyRows.length,
    duplicate_rows: duplicateRows,
    header,
    csv_rows: csvRows
  }
}];

const data = $input.first().json;
const csvRows = data.csv_rows || [];

function escapeCsv(value) {
  const text = value === undefined || value === null ? '' : String(value);
  if (/[",\n\r]/.test(text)) {
    return `"${text.replace(/"/g, '""')}"`;
  }
  return text;
}

const csvText = csvRows.map((row) => row.map(escapeCsv).join(',')).join('\n');
const baseName = String(data.file_name || 'database').replace(/\.[^.]+$/, '');
const csvFileName = `${baseName}.csv`;

return [{
  json: {
    chat_id: data.chat_id,
    user_id: data.user_id,
    file_name: data.file_name,
    valid: data.valid,
    message: data.message,
    issues: data.issues,
    csv_filename: csvFileName
  },
  binary: {
    data: {
      data: Buffer.from(csvText, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName: csvFileName,
      fileExtension: 'csv'
    }
  }
}];
